/* You can add global styles to this file, and also import other style files */
body {
  visibility: hidden;
}

/* Prevent background scroll when any Bootstrap modal is open */
html:has(body.modal-open) {
  overflow: hidden !important;
}
body.modal-open {
  overflow: hidden !important;
}
.z-index--1{
    position: relative;
    z-index: -1;
}

.apexcharts-tooltip {
    overflow: visible !important;
    z-index: 9999 !important;
}

.apexcharts-text {
  fill: var(--chart-lable-color);
}
.apexcharts-text.apexcharts-datalabel-label{
  fill: var(--chart-lable-color);
}
.apexcharts-text.apexcharts-datalabel-value{
  fill: var(--chart-value-color);
}
.mat-calendar-body-cell-content{
  color: var(--chart-lable-color) !important;
}
.mat-calendar-body-cell-content.mat-calendar-body-today{
  color: white !important;
}
.mat-calendar-body-cell-content:hover{
  color: white !important;
}
.mat-calendar-previous-button, .mat-calendar-next-button, .mat-calendar-body-label, .mdc-button__label, .mat-calendar-arrow{
  color: var(--chart-value-color) !important;
}
.mat-calendar-arrow{
  fill: var(--chart-value-color) !important;
}
.mat-calendar-table-header th[scope=col]{
  background-color: var(--chart-value-color);
}
.mat-calendar-body-cell:not(.mat-calendar-body-disabled):hover > .mat-calendar-body-cell-content:not(.mat-calendar-body-selected):not(.mat-calendar-body-comparison-identical){
  color: white !important;
}

input[type=date]{
  color-scheme: var(--color-scheme);
}
.dotsContainer:hover .boxSize{
  display: flex;
}
.boxSize{
  display: none;
  position: absolute;
  align-items: center;
  border-collapse: collapse;
  top: 20px;
  padding: 5px;
  right: -20px;
  /* box-shadow: 0px 0px 5px 0px lightgray; */
  border: 1px solid lightgray;
  background-color: white;
  border-radius: 5px;
  font-size: 12px;
  color: gray;
  z-index: 999;
}
.boxSize .boxSize_box{
  width: 20px;
  height: 20px;
  border: 1px solid black;
  cursor: pointer;
  transition: 0.3s;
}
.boxSize .boxSize_box:hover{
  background-color: green;
}
.boxSize_box:nth-child(2):has(+ .boxSize_box:nth-child(3):hover),
.boxSize_box:nth-child(3):has(+ .boxSize_box:nth-child(4):hover),
.boxSize_box:nth-child(2):has(+ .boxSize_box:nth-child(3) + .boxSize_box:nth-child(4):hover) {
  background-color: green;
}

.boxSize .boxSize_box.active{
  background-color: green;
}

.zoomContainer{
  width: 100%;
  height: 100vh;
  background-color: white;
  position: fixed;
  top: 0;
  left: 0;
  z-index: 9999;
}

.row .col-lg-6 .boxSize .boxSize_box:nth-child(2){
  background-color: green;
}

.row .col-lg-12 .boxSize .boxSize_box:nth-child(2){
  background-color: green;
}
.row .col-lg-12 .boxSize .boxSize_box:nth-child(3){
  background-color: green;
}
.nav-link{
  cursor: pointer;
}
.createmenunav{
  display: flex;
  flex-wrap: nowrap;
  white-space: nowrap;
  overflow-x: auto;
  overflow-y: clip;
}



.custom-quill-editor {
  border: 1px solid #b0b0b0db;
  border-radius: 5px;
  margin-bottom: 10px;
}
.custom-quill-editor .ql-container {
  height: 100px !important; /* Set content area height */
  overflow-y: auto; /* Enable scrolling */
}
.ql-toolbar{
  display: flex !important;
  gap: 5px;
}
.ql-editor.ql-blank::before {
  color: #888 !important;
  font-style: italic; 
  opacity: 1 !important;
}

.ql-toolbar .ql-formats{
   /* background-color: white !important; */
}
.ql-snow .ql-stroke{
  stroke: gray !important;
}

.ql-editor{
  /* background-color: white; */
}
.ql-picker-label{
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
}

.dark-placeholder::placeholder{
  color: black !important;
}
