  color: #0d99ff;
  position: absolute;
  content: '\e90d';
  font-family: 'icomoon' !important;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 12px;
}

.owl-nav .owl-next {
  position: absolute;
  top: 50%;
  right: -35px;
  transform: translate(-50%, -50%);
}

.owl-nav .owl-prev {
  position: absolute;
  top: 50%;
  left: 0px;
  transform: translate(-50%, -50%);
}

.owl-nav .owl-prev::after {
  color: #0d99ff;
  position: absolute;
  content: '\e916';
  font-family: 'icomoon' !important;
