/*  from notification.css  */
.btn-red{color: #EA4335; border: 1px solid #EA4335;}
.btn-red:hover{color: #ffffff; border: 1px solid transparent; background-color: #EA4335;}
.btn-red:hover svg path{fill: #fff;}
.btn-primary { background-color: #0D99FF; color: #fff;border: none; border: 1px solid transparent; }
.fs-12{font-size: 12px;}
/*  from roaster.css  */
h1,h2,h3,h4,h5,h6 {margin-bottom: 0;}
:root { --morning-bg: #FCB040; --evening-bg: #F599B8; --night-bg: #029D4A; --shift-morning-bg: rgba(252, 176, 64, 0.10000000149011612); --shift-morning-border: #FCB040; --shift-evening-bg: rgba(245, 153, 184, 0.10000000149011612); --shift-evening-border: #F599B8; --shift-night-bg: rgba(2, 157, 74, 0.10000000149011612); --shift-night-border: #029D4A;}
.btn.active,
.btn.show,
.btn:first-child:active,
:not(.btn-check)+.btn:active { background-color: #fff;}
.fs-16{font-size: 16px !important;}
[data-theme="dark"] .text-dark{color: #fff !important;}
