[data-theme="dark"] .table>:not(caption)>*>*{    background-color: var(--dark-1) !important;}
@media only screen and (max-width: 717px) {
.dashboard-body { margin-top: 96px;}}
/*  from schedule-interview.css  */
.controls {
    font-weight: 300 !important;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 10px;
}
.controls button {
    background: none;
    border: none;
    font-size: 40px;
    cursor: pointer;
    padding: 0 16px;
    color: #ffffff;
    transition: color 0.2s ease;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-top: -10px;
}
.controls button:hover {
    color: #d2d2d2;
}
