[data-theme="dark"] .ng-select.ng-select-single .ng-select-container,[data-theme="dark"] .ng-select.ng-select-multiple .ng-select-container {
  border:1px solid rgba(255, 255, 255, 0.3) !important;
  background-color: var(--dark-2);
  color: #fff !important;
}
[data-theme="dark"] .ng-select.ng-select-multiple .ng-input > input { color: #fff !important; caret-color: #fff !important; background-color: transparent !important; }
